#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# ──────────────────────────────────────────────────────────────────────────
# The CBOT board trigger (owner decision on #622, 2026-11-25): a cron-job.org
# job that POSTs GitHub's workflow-dispatch API for refresh-prices.yml with
# slot=board at 01:00 America/New_York, Tuesday to Saturday. Shared by
# scripts/setup_cbot_board_trigger.sh and scripts/check_cbot_board_trigger.sh.
# Secrets are never written to disk except the 0600 temp job body, removed
# on exit. See .github/workflows/refresh-prices.yml and LATENCY.md §4.
# ──────────────────────────────────────────────────────────────────────────

REPO="philipbergman6-glitch/Mirror-Market"
WORKFLOW="refresh-prices.yml"
JOB_TITLE="Mirror-Market CBOT board refresh"
TOKEN_NAME="mirror-market-board-dispatch"
# The trigger MUST run in New York time: Yahoo finishes the CBOT bar at
# 00:00 New York, so the job follows New York's DST, not UTC's.
JOB_TZ="America/New_York"
FIRE_HOUR=1
FIRE_MIN=0
FIRE_WDAYS="2,3,4,5,6"   # cron-job.org: 0 = Sunday … 6 = Saturday → Tue–Sat
DISPATCH_BODY='{"ref":"main","inputs":{"slot":"board"}}'
GH_API="https://api.github.com/repos/$REPO/actions/workflows/$WORKFLOW"
CJ_API="https://api.cron-job.org"

# Secrets reach curl through a config on stdin, never through argv.
gh_call() {   # gh_call METHOD URL [BODY] -> prints the HTTP status
  local method="$1" url="$2" body="${3:-}"
  curl -sS -o /dev/null -w '%{http_code}' -X "$method" "$url" \
    -H "Accept: application/vnd.github+json" \
    ${body:+-H "Content-Type: application/json" -d "$body"} \
    -K - <<CFG
header = "Authorization: Bearer $GH_DISPATCH_TOKEN"
CFG
}
cj_call() {   # cj_call METHOD PATH [BODY_FILE] -> prints the response body
  local method="$1" path="$2" body_file="${3:-}"
  curl -sS --fail-with-body -X "$method" "$CJ_API$path" \
    -H "Content-Type: application/json" \
    ${body_file:+--data-binary "@$body_file"} \
    -K - <<CFG
header = "Authorization: Bearer $CRONJOB_API_KEY"
CFG
}

# job_body FILE — the canonical job, token included, written to FILE (0600).
job_body() {
  local file="$1"
  (umask 077 && : > "$file")
  GH_DISPATCH_TOKEN="$GH_DISPATCH_TOKEN" JOB_TITLE="$JOB_TITLE" GH_API="$GH_API" \
  JOB_TZ="$JOB_TZ" FIRE_HOUR="$FIRE_HOUR" FIRE_MIN="$FIRE_MIN" FIRE_WDAYS="$FIRE_WDAYS" \
  DISPATCH_BODY="$DISPATCH_BODY" python3 - > "$file" <<'PY'
import json, os
print(json.dumps({"job": {
    "title": os.environ["JOB_TITLE"],
    "url": os.environ["GH_API"] + "/dispatches",
    "enabled": True,
    "saveResponses": True,
    "requestMethod": 1,
    "schedule": {
        "timezone": os.environ["JOB_TZ"],
        "hours": [int(os.environ["FIRE_HOUR"])],
        "minutes": [int(os.environ["FIRE_MIN"])],
        "mdays": [-1],
        "months": [-1],
        "wdays": [int(d) for d in os.environ["FIRE_WDAYS"].split(",")],
    },
    "notification": {"onFailure": True, "onDisable": True},
    "extendedData": {
        "headers": {
            "Authorization": "Bearer " + os.environ["GH_DISPATCH_TOKEN"],
            "Accept": "application/vnd.github+json",
            "Content-Type": "application/json",
        },
        "body": os.environ["DISPATCH_BODY"],
    },
}}))
PY
}

# main_has_board_slot — true once the PR adding the `slot` input is on main.
# Before that GitHub answers every dispatch with 422 (unexpected input).
main_has_board_slot() {
  # Decode into a variable first, then match. Piped straight into `grep -q`
  # under `set -o pipefail`, grep exits on the first match, base64 dies of
  # SIGPIPE (exit 141) mid-write, and the check reads "no slot input" on a
  # main that has it — observed on macOS 2026-11-26.
  local workflow
  workflow=$(gh api "repos/$REPO/contents/.github/workflows/$WORKFLOW?ref=main" --jq .content \
    | base64 --decode) || {
    warn "could not read main's $WORKFLOW from GitHub (gh api / base64 failed above)"
    return 1
  }
  grep -qE '^      slot:$' <<<"$workflow"
}

# in_on_time_window — a test dispatch now should end green: Tue–Sat New York,
# between 00:05 (bar final at 00:00) and 02:00 (inside the 12 h objective).
in_on_time_window() {
  local dow hm
  dow=$(TZ="$JOB_TZ" date +%u); hm=$(TZ="$JOB_TZ" date +%H%M)
  (( dow >= 2 && dow <= 6 )) && (( 10#$hm >= 5 && 10#$hm < 200 ))
}
run_wizard() {

TOTAL_STAGES=5

banner "Mirror-Market — why is the CBOT board trigger not firing?"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "GitHub — what the board slot actually did"
command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 \
  || { warn "gh is not installed or not logged in — run: gh auth login"; exit 1; }
if main_has_board_slot; then
  printf '  %s✓ main has the slot input%s\n' "$GREEN" "$RESET"
else
  warn "main's $WORKFLOW has no 'slot' input: every dispatch is refused with HTTP 422."
  say "That is the whole diagnosis: merge the board-slot PR."
fi
say "Recent dispatched runs (newest first):"
gh run list --repo "$REPO" --workflow "$WORKFLOW" --event workflow_dispatch --limit 12 \
  --json displayTitle,conclusion,createdAt \
  --jq '.[] | "    \(.createdAt)  \(.conclusion // "running")  \(.displayTitle)"' || warn "gh run list failed"
note "A missing 'Refresh Prices (board)' on a Tue–Sat morning = cron-job.org did not call GitHub."
note "A red one = it was called; open it — the cause is in GitHub, not cron-job.org."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "cron-job.org — API key, then read the job"
open_url "https://console.cron-job.org/settings"
step "Settings → API keys: copy the existing key, or create one (no IP restriction)."
ask_secret CRONJOB_API_KEY "Paste the API key:" || { warn "no API key entered — stopping"; exit 1; }
[[ -n "$CRONJOB_API_KEY" ]] || { warn "no API key entered — stopping"; exit 1; }
if ! jobs_json=$(cj_call GET /jobs); then
  warn "cron-job.org rejected that key: $jobs_json"; exit 1
fi
printf '  %s✓ API key works%s\n' "$GREEN" "$RESET"
JOB_ID=$(printf '%s' "$jobs_json" | JOB_TITLE="$JOB_TITLE" python3 -c '
import json, os, sys
jobs = [j for j in json.load(sys.stdin).get("jobs", []) if j.get("title") == os.environ["JOB_TITLE"]]
print(" ".join(str(j["jobId"]) for j in jobs))')
if [[ "$JOB_ID" == *" "* ]]; then
  warn "SEVERAL jobs are titled '$JOB_TITLE' (ids $JOB_ID): each fires its own dispatch."
  say "Delete all but one in the console, then re-run this wizard."
  open_url "https://console.cron-job.org/jobs"
  exit 1
fi
if [[ -z "$JOB_ID" ]]; then
  warn "NO job titled '$JOB_TITLE' exists in this account."
  say "That is the diagnosis: the setup wizard's job stage was skipped or answered 'N'."
  say "All jobs in the account:"
  printf '%s' "$jobs_json" | python3 -c '
import json, sys
for j in json.load(sys.stdin).get("jobs", []):
    print("    #%s  enabled=%s  %r  %s" % (j["jobId"], j.get("enabled"), j.get("title"), j.get("url")))'
  NEED_CREATE=true
else
  NEED_CREATE=false
  printf '  %s✓ found job #%s%s\n' "$GREEN" "$JOB_ID" "$RESET"
  cj_call GET "/jobs/$JOB_ID" | JOB_TZ="$JOB_TZ" python3 -c '
import json, os, sys, datetime as dt
j = json.load(sys.stdin)["jobDetails"]
ts = lambda t: dt.datetime.fromtimestamp(t, dt.timezone.utc).strftime("%Y-%m-%d %H:%M UTC") if t else "never"
s = j.get("schedule", {})
ext = j.get("extendedData", {})
h = ext.get("headers", {})
auth = "present" if any(k.lower() == "authorization" for k in h) else "MISSING"
tz = s.get("timezone")
print("    enabled:        %s" % j.get("enabled"))
print("    url:            %s" % j.get("url"))
print("    method code:    %s   (1 = POST)" % j.get("requestMethod"))
print("    schedule:       %s hours=%s minutes=%s wdays=%s" % (tz, s.get("hours"), s.get("minutes"), s.get("wdays")))
if tz != os.environ["JOB_TZ"]:
    print("    !! timezone is %r, not %s — the trigger drifts an hour across DST; stage 5 fixes it" % (tz, os.environ["JOB_TZ"]))
print("    last status:    %s   (1 OK, 2 DNS, 3 connect, 4 HTTP error, 5 timeout, 6 size, 7 URL, 8 internal)" % j.get("lastStatus"))
print("    last run:       %s" % ts(j.get("lastExecution")))
print("    next run:       %s" % ts(j.get("nextExecution")))
print("    auth header:    %s" % auth)
print("    body:           %s" % ext.get("body"))'
  say ""
  say "Execution history (newest first):"
  cj_call GET "/jobs/$JOB_ID/history" | python3 -c '
import json, sys, datetime as dt
rows = json.load(sys.stdin).get("history", [])
if not rows: print("    (empty — the scheduler has never run the job)")
for r in rows[:15]:
    when = dt.datetime.fromtimestamp(r["date"], dt.timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    print("    %s  http=%s  status=%s  %s" % (when, r.get("httpStatus"), r.get("status"), r.get("statusText", "")))'
  say ""
  say "Reading the result:"
  note "  enabled=False          → cron-job.org disabled it after repeated failures; stage 5 re-enables."
  note "  http=401 / 403         → the token is expired, revoked, or lacks Actions write; stage 3 rotates it."
  note "  http=404               → wrong repo/workflow path, or token not scoped to this repo."
  note "  http=422               → bad body, or main has no 'slot' input (stage 1 says which)."
  note "  http=204 every day     → GitHub accepted it; the problem is on GitHub's side — stop and tell Claude."
  note "  history empty          → job exists but its schedule never matched; stage 5 rewrites it."
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "GitHub — the dispatch token"
say "The job authenticates with a fine-grained token named $TOKEN_NAME."
note "GitHub never shows a token's value again, so re-saving the job needs a fresh one."
open_url "https://github.com/settings/personal-access-tokens"
step "Find '$TOKEN_NAME'. If it exists: open it → 'Regenerate token' → copy the value."
step "If not: 'Generate new token' → name $TOKEN_NAME, custom expiry up to 1 year,"
step "  'Only select repositories' → Mirror-Market, Actions → 'Read and write'. Copy it."
ask_secret GH_DISPATCH_TOKEN "Paste the token:" || { warn "no token entered — stopping"; exit 1; }
[[ -n "$GH_DISPATCH_TOKEN" ]] || { warn "no token entered — stopping"; exit 1; }
status=$(gh_call GET "$GH_API")
if [[ "$status" != "200" ]]; then
  warn "GitHub answered HTTP $status for that token — expected 200. Check repo scope + Actions permission, re-run."
  exit 1
fi
printf '  %s✓ token can read the workflow%s\n' "$GREEN" "$RESET"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Prove the token can start a board refresh — the exact call cron-job.org makes"
if in_on_time_window; then
  note "Inside the on-time window (Tue–Sat, 00:05–02:00 New York): this run should end green."
else
  warn "Outside the on-time window. The run publishes normally but ends RED at the latency gate."
  note "That red is expected and still proves the trigger works. Do not fire it while a deploy to main is running."
fi
if confirm "Fire one board refresh now?"; then
  status=$(gh_call POST "$GH_API/dispatches" "$DISPATCH_BODY")
  if [[ "$status" == 2* ]]; then
    printf '  %s✓ GitHub accepted the dispatch (HTTP %s)%s\n' "$GREEN" "$status" "$RESET"
    open_url "https://github.com/$REPO/actions/workflows/$WORKFLOW"
    step "A run named 'Refresh Prices (board)' appears within a minute."
  else
    warn "GitHub answered HTTP $status — this token cannot trigger the board slot. Fix it and re-run."
    exit 1
  fi
else
  SKIPPED+=("test dispatch (not fired)")
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "cron-job.org — write the job back with the working token"
body_file=$(mktemp); trap 'rm -f "$body_file"' EXIT
job_body "$body_file"
if [[ "$NEED_CREATE" == true ]]; then
  say "No job exists — creating it: POST GitHub dispatch, Tue–Sat 01:00 $JOB_TZ, e-mail on failure/disable."
  if confirm "Create the job now?"; then
    created=$(cj_call PUT /jobs "$body_file") || { warn "cron-job.org refused: $created"; exit 1; }
    printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$created"
  else
    SKIPPED+=("cron-job.org job (not created)")
  fi
else
  say "Job #$JOB_ID exists — re-saving it enabled, with the fresh token and the canonical"
  say "schedule (01:00 $JOB_TZ, Tue–Sat) and body ($DISPATCH_BODY)."
  if confirm "Update job #$JOB_ID now?"; then
    cj_call PATCH "/jobs/$JOB_ID" "$body_file" >/dev/null || { warn "cron-job.org refused the update"; exit 1; }
    printf '  %s✓ updated%s\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("cron-job.org job #$JOB_ID (not updated)")
  fi
fi
rm -f "$body_file"
open_url "https://console.cron-job.org/jobs"
step "Confirm the job is listed, enabled, timezone $JOB_TZ, next execution 01:00 on a Tue–Sat."
pause
# ──────────────────────────────────────────────────────────────────────────

finish
}

run_wizard "$@"; exit
